import copy

TABLES = ['schedule', 'designs', 'exposures', 'orders', 'closures', 'coverage']

def exposure_coverage(snapshot, options):
    from collections import Counter
    schedules = snapshot['schedule']
    observed = {row['event_period'] for row in snapshot['exposures']}
    orders = snapshot['orders']
    return {'periods': len(schedules), 'sequences': len({r['sequence'] for r in schedules}),
            'exposed_periods': len(observed), 'unobserved_periods': sorted(set(r['period'] for r in schedules)-observed),
            'assigned': dict(Counter(str(r['assigned']) for r in schedules)),
            'orders': len(orders), 'closures': len(snapshot['closures'])}

